#!/usr/bin/env sh
# detect-plugins-prep-env-setup.sh
# Build-time script: detect /usr/local/bin/chainlink-* and write /etc/chainlink/env-setup.sh
set -eu

OUT_DIR=/etc/chainlink
OUT_FILE=${OUT_DIR}/env-setup.sh
TMP=$(mktemp)

mkdir -p "${OUT_DIR}"

cat > "${TMP}" <<'EOF'
# generated by detect-plugins-prep-env-setup.sh
# Each line exports CL_<PLUGIN>_CMD using parameter expansion so runtime -e can override:
#   export CL_FOO_CMD="${CL_FOO_CMD:-/usr/local/bin/chainlink-foo}"
EOF

# iterate matching plugin binaries
for f in /usr/local/bin/chainlink-*; do
  [ "$f" = "/usr/local/bin/chainlink-*" ] && continue
  [ -x "$f" ] || continue
  base=$(basename "$f")     # chainlink-<plugin>
  plugin=${base#chainlink-} # <plugin>
  var=$(printf '%s' "$plugin" | tr '[:lower:]' '[:upper:]' | tr '-' '_')
  
  # Use short binary name (chainlink-foo); allow runtime override via ${VAR:-value}
  printf 'export CL_%s_CMD="${CL_%s_CMD:-%s}"\n' "$var" "$var" "$base" >> "${TMP}"
  
#   TODO: future option for using the full path instead of short name
#   # Use full path so runtime PATH changes don't break; allow runtime override via ${VAR:-value}
#   printf 'export CL_%s_CMD="${CL_%s_CMD:-%s}"\n' "$var" "$var" "$f" >> "${TMP}"
done

# If no plugins found, still create a file (noop)
mv "${TMP}" "${OUT_FILE}"
rm -f "${TMP}"
chmod 644 "${OUT_FILE}"
